  problem:{title:"The Welcome Festival", text:["A school in Fujairah is planning a Welcome Festival for new families from many countries, including several from Africa. Some parents complain that the festival is 'too mixed' and will be 'unsafe'.","Students want to show that a diverse school can also be a safe, united community. They plan stalls on African history and different cultures."],
    qs:[["Identify the problem(s) described in the text.","Prejudice against new families; fear that diversity is unsafe."],["What are the consequences if the festival is cancelled?","New families feel excluded; the school community is divided."],["Suggest how students can make the festival safe and welcoming.","A clear safety plan; invite all parents; stalls on cultures and Africa."],["How are community, safety and diversity connected in this case?","A safe community welcomes everyone; tolerance builds trust."]]},
  create:{title:"My Term 1 Revision", options:[["Mind map","A mind map of all three units, with key terms, one fact and one UAE example for each."],["Quiz cards","Eight quiz cards (question on the front, answer on the back) covering Units 1–3."],["Summary poster","A summary poster showing the most important idea from each unit."]], must:["All three units","Key terms defined","UAE examples","A clear title"]},
